Path('responses').mkdir(parents=True, exist_ok=True)
for i, chunk in enumerate(chunks):
    try:
        response = client.chat.completions.create(model=model, messages=[
            {"role": "system", "content": "You are a programming assistant integrated with GitHub Actions. Respond only in valid JSON."},
            {"role": "user", "content": chunk}
        ])
        reply = response.choices[0].message.content.strip()
        # validate JSON
        try:
            parsed = json.loads(reply)
            Path(f"responses/chunk_{i:04d}.json").write_text(json.dumps(parsed, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as parse_err:
            Path(f"responses/chunk_{i:04d}.error.json").write_text(json.dumps({"raw": reply, "parse_error": str(parse_err)}), encoding="utf-8")
        time.sleep(0.5)
    except Exception as e:
        # consider exponential backoff / retries here
        Path(f"responses/chunk_{i:04d}.exception.json").write_text(json.dumps({"error": str(e)}), encoding="utf-8")
print("✅ All chunks processed.")
